#include "stdlib/math/base/special/log10f.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/constants/float32/abs_mask.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/constants/float32/exponent_bias.h"
#include "stdlib/constants/float32/significand_mask.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/math/base/special/kernel_log1pf.h"
#include <math.h>

static const float TWO25 = 3.3554432000e+07; // 0x4c000000
static const float IVLN10HI = 4.3432617188e-01; // 0x3ede6000
static const float IVLN10LO = -3.1689971365e-05; // 0xb804ead9
static const float LOG10_2HI = 3.0102920532e-01; // 0x3e9a2080
static const float LOG10_2LO = 7.9034151668e-07; // 0x355427db
static const int32_t HIGH_MAX_NORMAL_EXP = 0x7f800000;
static const int32_t HIGH_MIN_NORMAL_EXP = 0x00800000;
static const int32_t HIGH_BIASED_EXP_0 = 0x3f800000;

/**
* Evaluates the common logarithm (base ten) of a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log10f( 4.0 );
* // returns ~0.602
*/
float stdlib_base_log10f( float x ){
	int32_t i;
	int32_t k;
	uint32_t hx;
	float xc;
	int32_t ihx;
	float y;
	float hfsq;
	float r;
	float hi;
	float lo;
	float f;

	if ( stdlib_base_is_nanf( x ) || x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	xc = x;
	stdlib_base_float32_to_word( xc, &hx );
	ihx = (int32_t)hx;
	k=0;
	if ( ihx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-126
		if ( ( ihx & STDLIB_CONSTANT_FLOAT32_ABS_MASK ) == 0 ) {
			return STDLIB_CONSTANT_FLOAT32_NINF;
		}
		k -= 25;

		// Subnormal number, scale up x:
		xc *= TWO25;
		stdlib_base_float32_to_word( xc, &hx );
		ihx = (int32_t)hx;
	}
	if ( ihx >= HIGH_MAX_NORMAL_EXP  ) {
		return xc + xc ;
	}
	// Case: log(1) = +0
	if ( ihx == HIGH_BIASED_EXP_0 ) {
		return 0;
	}
	k += ( ( ihx>> 23 ) - STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS );
	ihx &= STDLIB_CONSTANT_FLOAT32_SIGNIFICAND_MASK;
	i = ( ihx + 0x4afb0d ) & HIGH_MIN_NORMAL_EXP;
	// Normalize x or x/2...
	stdlib_base_float32_from_word( (uint32_t)( ihx | ( i ^ HIGH_BIASED_EXP_0 ) ), &xc );
	k += ( i >> 23 );
	y = (float)k;
	f = xc - (float)1.0;
	hfsq = (float)0.5*f*f;
	r = stdlib_base_kernel_log1pf( f );
	if ( sizeof( float_t ) > sizeof( float ) ) {
		return ( r - hfsq + f )*( (float_t)IVLN10LO + IVLN10HI ) + y*( (float_t)LOG10_2LO + LOG10_2HI );
	}
	hi = f - hfsq;
	stdlib_base_float32_to_word( ihx, &hi );
	stdlib_base_float32_from_word( hi, ihx & 0xfffff000 );
	lo = ( f - hi ) - hfsq + r ;
	return y * LOG10_2LO + ( lo + hi ) * IVLN10LO + lo * IVLN10HI + hi * IVLN10HI + y * LOG10_2HI;
}
// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return 0.3999999999940942f + (x * (0.22222198432149784f + (x * 0.15313837699209373f)));
}

// END: polyval_p// BEGIN: polyval_q

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_q( const float x ) {
	return 0.6666666666666735f + (x * (0.2857142874366239f + (x * (0.1818357216161805f + (x * 0.14798198605116586f)))));
}

// END: polyval_q
